<?php require "../config/auth.php";require "../config/koneksi.php";require "../templates.php";if(isset($_POST['simpan'])){$t=$conn->real_escape_string($_POST['tanggal']);$k=$conn->real_escape_string($_POST['kelas']);$n=$conn->real_escape_string($_POST['nama_siswa']);$s=$conn->real_escape_string($_POST['status']);$conn->query("INSERT INTO absensi(tanggal,kelas,nama_siswa,status) VALUES('$t','$k','$n','$s')");header("Location:index.php");exit;}head("Absensi");?>
<h2>Absensi</h2><div class="card p-3 my-3"><form method="post" class="row g-2"><div class="col-md-2"><input type="date" name="tanggal" class="form-control" required></div><div class="col-md-2"><input name="kelas" class="form-control" placeholder="Kelas" required></div><div class="col-md-4"><input name="nama_siswa" class="form-control" placeholder="Nama siswa" required></div><div class="col-md-2"><select name="status" class="form-select"><option>Hadir</option><option>Izin</option><option>Sakit</option><option>Alfa</option></select></div><div class="col-md-2"><button name="simpan" class="btn btn-dark w-100">Simpan</button></div></form></div><div class="card p-3"><table class="table"><tr><th>Tanggal</th><th>Kelas</th><th>Siswa</th><th>Status</th></tr><?php $q=$conn->query("SELECT * FROM absensi ORDER BY id DESC");while($r=$q->fetch_assoc()):?><tr><td><?=$r['tanggal']?></td><td><?=$r['kelas']?></td><td><?=$r['nama_siswa']?></td><td><?=$r['status']?></td></tr><?php endwhile;?></table></div><?php foot();?>